/**
 * Specimen tiles for the landing page — real frames from real projects on this
 * deployment, each carrying the segmentation the named model actually produced.
 *
 * GENERATED, do not hand-edit the geometry. Every `outlines` entry is a
 * Ramer-Douglas-Peucker simplification of the polygons/polylines stored for
 * that image, remapped from source pixels into the tile's 1000x1000 viewBox.
 * `stroke` mirrors the colour rules in
 * `pages/segmentation/components/canvas/CanvasPolygon.tsx`, so a tile shows the
 * same colours the editor will: red external contour, sky internal contour,
 * green spheroid core and sperm head, amber midpiece, cyan tail, grey for a
 * border-cut microcapsule, and a per-track hue for a tracked microtubule.
 *
 * The human-readable label, detail line and alt text live in
 * `landing.specimens.<id>.*` in the translation files, not here.
 */

/** Ids are the tile ids, NOT project types: `disintegration` is the tile for
 *  the `spheroid_invasive` project type. */
export type SpecimenId =
  | 'spheroid'
  | 'disintegration'
  | 'wound'
  | 'sperm'
  | 'microtubule'
  | 'microcapsule';

export interface SpecimenOutline {
  /** SVG path in the tile's 1000x1000 viewBox. Closed (`Z`) for polygons. */
  readonly d: string;
  /** Stroke colour, matching what the segmentation editor draws. */
  readonly stroke: string;
}

export interface Specimen {
  readonly id: SpecimenId;
  /** Path under /public. */
  readonly image: string;
  /** Model that produced these outlines (`model_used` on the stored result). */
  readonly model: string;
  /** Project type this specimen belongs to, as used by `PROJECT_TYPES`. */
  readonly projectType: string;
  readonly outlines: readonly SpecimenOutline[];
}

